insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('f05c29af-eded-4876-95bb-08c74437841d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Sculpture as Object, Space, Material, and Experience', 'This opening unit frames sculpture as more than an object. Students learn to think across material presence, spatial placement, viewer movement, historical reference, and lived experience.', 0),
  ('92464d2a-7215-433d-a6b7-72b3b35e63fc', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'f05c29af-eded-4876-95bb-08c74437841d', 'subtopic'::public.curated_course_node_type, 'Object and Thingness', 'Students learn why sculptural meaning begins with physical presence: weight, surface, size, resistance, orientation, and how an object occupies attention.', 0),
  ('2e1ba199-c89f-4f8d-808e-bf33f55d968a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '92464d2a-7215-433d-a6b7-72b3b35e63fc', 'concept'::public.curated_course_node_type, 'Objecthood and material presence', null, 0),
  ('09c10986-2954-4309-a293-192aa5cc192a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '92464d2a-7215-433d-a6b7-72b3b35e63fc', 'concept'::public.curated_course_node_type, 'Autonomy versus context', null, 1),
  ('3763837c-1cb8-4f70-ab9c-6244581d389f', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '92464d2a-7215-433d-a6b7-72b3b35e63fc', 'concept'::public.curated_course_node_type, 'Pedestals, supports, and display conventions', null, 2),
  ('6998a1e8-cce4-4e5f-8704-ca61d12c3a4f', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '92464d2a-7215-433d-a6b7-72b3b35e63fc', 'concept'::public.curated_course_node_type, 'Touch, proximity, and bodily scale', null, 3),
  ('7166ef05-f741-4697-bf1a-3701c8b32f0f', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'f05c29af-eded-4876-95bb-08c74437841d', 'subtopic'::public.curated_course_node_type, 'Space and Viewer Experience', 'The point is to see sculpture as something encountered through movement rather than absorbed from a single fixed viewpoint.', 1),
  ('fffa32ee-df14-4769-8628-fe3c9eb17916', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '7166ef05-f741-4697-bf1a-3701c8b32f0f', 'concept'::public.curated_course_node_type, 'Frontality and all-around viewing', null, 0),
  ('6d061c77-20be-4b29-8d2e-6d73cd2dab25', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '7166ef05-f741-4697-bf1a-3701c8b32f0f', 'concept'::public.curated_course_node_type, 'Sight lines and circulation', null, 1),
  ('e85ca964-086d-44d5-9780-f08f1380d9d6', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '7166ef05-f741-4697-bf1a-3701c8b32f0f', 'concept'::public.curated_course_node_type, 'Void, interval, and negative space', null, 2),
  ('056295ad-d647-4352-90f3-3ce8f737571e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '7166ef05-f741-4697-bf1a-3701c8b32f0f', 'concept'::public.curated_course_node_type, 'Temporal experience and sequence', null, 3),
  ('0135cc58-930d-432f-bd22-e51154732fe1', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'f05c29af-eded-4876-95bb-08c74437841d', 'subtopic'::public.curated_course_node_type, 'Concept, Context, and Encounter', 'Students connect formal choices to ideas, locations, histories, and audiences so that making decisions carry intellectual force.', 2),
  ('6b36cf25-04ff-48ef-bb73-52243def2c1e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0135cc58-930d-432f-bd22-e51154732fe1', 'concept'::public.curated_course_node_type, 'Site and institutional context', null, 0),
  ('48441443-b54f-48c1-bc01-45586be456be', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0135cc58-930d-432f-bd22-e51154732fe1', 'concept'::public.curated_course_node_type, 'Narrative, symbol, and metaphor', null, 1),
  ('d3205542-1517-4a12-859e-7ffd500fd908', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0135cc58-930d-432f-bd22-e51154732fe1', 'concept'::public.curated_course_node_type, 'Embodiment and phenomenology', null, 2),
  ('0008ea9a-94c8-4033-9cca-792aa8ba64ca', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0135cc58-930d-432f-bd22-e51154732fe1', 'concept'::public.curated_course_node_type, 'Audience, participation, and interpretation', null, 3),
  ('8b031c1a-5d88-4900-b144-f6961b55f203', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Three-Dimensional Design: Form, Volume, Mass, Scale, and Space', 'This unit builds the visual grammar of 3-D work. Students learn to compose with form, mass, volume, scale, proportion, gravity, and spatial relationships before committing to complex materials.', 1),
  ('0bd1d0fe-2242-40cd-830b-5101da26bfa7', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '8b031c1a-5d88-4900-b144-f6961b55f203', 'subtopic'::public.curated_course_node_type, 'Form, Volume, and Mass', 'Students develop control over the basic sculptural elements that make an object feel light, dense, dynamic, stable, compressed, or expansive.', 0),
  ('5ed7dc4b-4ced-4304-b305-3bbfa27d145c', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0bd1d0fe-2242-40cd-830b-5101da26bfa7', 'concept'::public.curated_course_node_type, 'Geometric and organic form', null, 0),
  ('73e0bb8e-8356-4cfa-8582-7e03292cba45', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0bd1d0fe-2242-40cd-830b-5101da26bfa7', 'concept'::public.curated_course_node_type, 'Solid mass versus implied volume', null, 1),
  ('b6453db6-3217-42c6-b5cd-9493668de070', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0bd1d0fe-2242-40cd-830b-5101da26bfa7', 'concept'::public.curated_course_node_type, 'Positive and negative space', null, 2),
  ('bba820f9-d6d6-4674-a50c-97ec8e3eeae7', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0bd1d0fe-2242-40cd-830b-5101da26bfa7', 'concept'::public.curated_course_node_type, 'Proportion, rhythm, and repetition', null, 3),
  ('55424d1c-3b2b-4984-af10-2526d485dd06', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '8b031c1a-5d88-4900-b144-f6961b55f203', 'subtopic'::public.curated_course_node_type, 'Scale and Human Reference', 'The gist is learning how scale changes meaning, from hand-held object to architectural intervention to public monument.', 1),
  ('e6c4371d-9bfd-42c4-9632-9e4e1907765f', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '55424d1c-3b2b-4984-af10-2526d485dd06', 'concept'::public.curated_course_node_type, 'Maquettes and scale models', null, 0),
  ('b1725d14-4f4e-4e4e-8dcb-7a8d9f2825e1', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '55424d1c-3b2b-4984-af10-2526d485dd06', 'concept'::public.curated_course_node_type, 'Body scale and ergonomic reference', null, 1),
  ('6f8df4b2-7cf4-4eb3-ba4d-b28cdbe6e99d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '55424d1c-3b2b-4984-af10-2526d485dd06', 'concept'::public.curated_course_node_type, 'Monumentality and intimacy', null, 2),
  ('d0a5dda0-30fc-49f0-ae68-a4fb6dfacecd', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '55424d1c-3b2b-4984-af10-2526d485dd06', 'concept'::public.curated_course_node_type, 'Measurement, enlargement, and translation', null, 3),
  ('baec9511-d1b8-4be3-b769-95f5ea651ccb', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '8b031c1a-5d88-4900-b144-f6961b55f203', 'subtopic'::public.curated_course_node_type, 'Balance, Gravity, and Spatial Tension', 'Students learn that sculpture must persuade both the eye and the body; it has to look intentional and often has to stand safely.', 2),
  ('f157a4f8-b8f3-4b17-84b3-865d22cbf919', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'baec9511-d1b8-4be3-b769-95f5ea651ccb', 'concept'::public.curated_course_node_type, 'Center of gravity', null, 0),
  ('74652923-57b8-48f5-92de-825ff70cb328', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'baec9511-d1b8-4be3-b769-95f5ea651ccb', 'concept'::public.curated_course_node_type, 'Cantilever and counterweight', null, 1),
  ('c604b5cb-ac18-4c41-bf13-41e7ba79bb05', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'baec9511-d1b8-4be3-b769-95f5ea651ccb', 'concept'::public.curated_course_node_type, 'Symmetry and asymmetry', null, 2),
  ('a5d996a7-22ea-4cef-bbdf-e1bcdda8fadc', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'baec9511-d1b8-4be3-b769-95f5ea651ccb', 'concept'::public.curated_course_node_type, 'Visual tension versus physical stability', null, 3),
  ('64988136-2eae-43a7-88c6-733d11754df4', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Materials, Tools, Studio Safety, and Shop Literacy', 'A world-class sculpture course treats safety and shop literacy as creative infrastructure. Students learn to choose materials intelligently, handle tools responsibly, and plan work before risks accumulate.', 2),
  ('be755742-0fb4-4f7d-be5c-7c6dd0f3017f', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '64988136-2eae-43a7-88c6-733d11754df4', 'subtopic'::public.curated_course_node_type, 'Material Families and Properties', 'Students compare materials by strength, flexibility, weight, toxicity, workability, cost, durability, and expressive potential.', 0),
  ('518703fb-92ab-4911-a15c-e6c790b665ba', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'be755742-0fb4-4f7d-be5c-7c6dd0f3017f', 'concept'::public.curated_course_node_type, 'Clay, plaster, wood, metal, foam, plastics, textiles', null, 0),
  ('d6784ac9-caf0-4083-b67a-a7cfec67c31d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'be755742-0fb4-4f7d-be5c-7c6dd0f3017f', 'concept'::public.curated_course_node_type, 'Structural and surface properties', null, 1),
  ('1fe7636a-48e2-45f4-8503-9ab0da6ac347', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'be755742-0fb4-4f7d-be5c-7c6dd0f3017f', 'concept'::public.curated_course_node_type, 'Archival and temporary materials', null, 2),
  ('e9f7dad8-8f53-4ca9-aec2-9cc300eb876a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'be755742-0fb4-4f7d-be5c-7c6dd0f3017f', 'concept'::public.curated_course_node_type, 'Material tests and sample boards', null, 3),
  ('197ad5c7-9084-4f85-9c6a-3e3e3dad7aae', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '64988136-2eae-43a7-88c6-733d11754df4', 'subtopic'::public.curated_course_node_type, 'Tool Use and Shop Workflow', 'The point is to make students more independent in the studio while respecting shared equipment and time.', 1),
  ('9ad2c71f-017a-49c3-8474-bac36087afae', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '197ad5c7-9084-4f85-9c6a-3e3e3dad7aae', 'concept'::public.curated_course_node_type, 'Hand tools and power tools', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('5e1a2cf2-1169-4057-a235-316077e9d694', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '197ad5c7-9084-4f85-9c6a-3e3e3dad7aae', 'concept'::public.curated_course_node_type, 'Clamps, vises, jigs, and fixtures', null, 1),
  ('7ae9d1e8-daf8-4582-8314-7cb5c2e9a778', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '197ad5c7-9084-4f85-9c6a-3e3e3dad7aae', 'concept'::public.curated_course_node_type, 'Measuring, marking, cutting, and assembly', null, 2),
  ('8079811b-ce93-4b2a-82cf-00d03b656b1e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '197ad5c7-9084-4f85-9c6a-3e3e3dad7aae', 'concept'::public.curated_course_node_type, 'Maintenance, storage, and cleanup routines', null, 3),
  ('a46ad3c8-440b-47b8-91af-8dd1c2117f2d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '64988136-2eae-43a7-88c6-733d11754df4', 'subtopic'::public.curated_course_node_type, 'Safety, Risk, and Documentation', 'Students learn to make risk visible before they cut, cast, weld, sand, spray, lift, or install.', 2),
  ('a73ff11f-4fde-42b3-9cd0-3fd9c7441c00', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'a46ad3c8-440b-47b8-91af-8dd1c2117f2d', 'concept'::public.curated_course_node_type, 'Personal protective equipment', null, 0),
  ('b891efcd-38ff-4164-91b7-98e81dedcb75', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'a46ad3c8-440b-47b8-91af-8dd1c2117f2d', 'concept'::public.curated_course_node_type, 'Ventilation, dust, solvents, and fumes', null, 1),
  ('d4e66dca-9898-4c64-a04e-113ecc1de892', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'a46ad3c8-440b-47b8-91af-8dd1c2117f2d', 'concept'::public.curated_course_node_type, 'Material safety data sheets', null, 2),
  ('9bab3649-b5d3-4752-b419-1525b2e60037', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'a46ad3c8-440b-47b8-91af-8dd1c2117f2d', 'concept'::public.curated_course_node_type, 'Lifting, transport, and emergency procedures', null, 3),
  ('08dc9974-d480-4f74-9534-b287798010a2', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Additive Modeling: Clay, Wax, Plaster, Armatures, and Figure Construction', 'Additive modeling develops the hand, eye, and ability to build form gradually. Students work from gesture and mass toward structure, anatomy, surface, and expressive refinement.', 3),
  ('64eebbb4-71eb-4608-99da-9fc12d08de66', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '08dc9974-d480-4f74-9534-b287798010a2', 'subtopic'::public.curated_course_node_type, 'Clay, Wax, and Plaster Modeling', 'Students learn materials that invite revision, compression, addition, and expressive touch.', 0),
  ('aa2a6400-ba54-47e2-9ced-d214d85d935d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '64eebbb4-71eb-4608-99da-9fc12d08de66', 'concept'::public.curated_course_node_type, 'Coils, slabs, modeling, and joining', null, 0),
  ('0063d9f4-40eb-4634-a144-fff073813b8d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '64eebbb4-71eb-4608-99da-9fc12d08de66', 'concept'::public.curated_course_node_type, 'Wax modeling and repair', null, 1),
  ('05b5c02a-202c-4162-ab53-ca34649306b8', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '64eebbb4-71eb-4608-99da-9fc12d08de66', 'concept'::public.curated_course_node_type, 'Plaster buildup and carving back', null, 2),
  ('d5e6b2fc-6f79-47c1-a9e1-4f31cba72e0a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '64eebbb4-71eb-4608-99da-9fc12d08de66', 'concept'::public.curated_course_node_type, 'Drying, curing, and cracking control', null, 3),
  ('0a28038a-6a08-4fd6-8e67-e90432d94da1', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '08dc9974-d480-4f74-9534-b287798010a2', 'subtopic'::public.curated_course_node_type, 'Armatures and Internal Support', 'The gist is learning that hidden structure shapes what the surface can do.', 1),
  ('66fe3f13-ec07-4a9a-9fb7-4c19eb5d0d3b', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0a28038a-6a08-4fd6-8e67-e90432d94da1', 'concept'::public.curated_course_node_type, 'Wire, pipe, wood, and mixed armatures', null, 0),
  ('82e60471-d95d-4c5f-b7c7-3f4861e876aa', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0a28038a-6a08-4fd6-8e67-e90432d94da1', 'concept'::public.curated_course_node_type, 'Load, balance, and anchor points', null, 1),
  ('e5212dd5-6894-4d8f-b35b-391a4231e5aa', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0a28038a-6a08-4fd6-8e67-e90432d94da1', 'concept'::public.curated_course_node_type, 'Removable versus embedded supports', null, 2),
  ('7501dd60-9bb6-4c42-909b-5b261cb10b2e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0a28038a-6a08-4fd6-8e67-e90432d94da1', 'concept'::public.curated_course_node_type, 'Compatibility with clay, plaster, and casting', null, 3),
  ('b1dd393f-84e6-4e68-aecd-01373fda5125', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '08dc9974-d480-4f74-9534-b287798010a2', 'subtopic'::public.curated_course_node_type, 'Figure, Gesture, and Surface', 'Students learn how body-based observation strengthens both representational and abstract sculpture.', 2),
  ('48909b4f-91d0-42d7-a9bc-30be7737ee87', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b1dd393f-84e6-4e68-aecd-01373fda5125', 'concept'::public.curated_course_node_type, 'Gesture and pose', null, 0),
  ('5193f3b6-d749-4207-bc6a-fd3542659c7d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b1dd393f-84e6-4e68-aecd-01373fda5125', 'concept'::public.curated_course_node_type, 'Proportion and skeletal landmarks', null, 1),
  ('58e5f797-1b7a-4f4f-8342-2a7591d55677', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b1dd393f-84e6-4e68-aecd-01373fda5125', 'concept'::public.curated_course_node_type, 'Plane changes and anatomy overview', null, 2),
  ('951f83d3-159e-408f-88a6-790472026314', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b1dd393f-84e6-4e68-aecd-01373fda5125', 'concept'::public.curated_course_node_type, 'Texture, tool marks, and finish', null, 3),
  ('7584b66a-2a78-49d3-95dd-fe523edd9618', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Subtractive Processes: Carving, Cutting, Shaping, and Surface', 'Subtractive methods teach commitment, patience, and the intelligence of removal. Students learn how form emerges through cutting, carving, sanding, scraping, and surface decisions.', 4),
  ('b2181331-c9d0-437e-82f6-f4c23ebbfc6f', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '7584b66a-2a78-49d3-95dd-fe523edd9618', 'subtopic'::public.curated_course_node_type, 'Carving Logic', 'Students learn to think from the outside inward, preserving what matters while removing what does not.', 0),
  ('58dcdc81-466e-4c11-968e-abfd28bd1116', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b2181331-c9d0-437e-82f6-f4c23ebbfc6f', 'concept'::public.curated_course_node_type, 'Block planning and profile drawings', null, 0),
  ('30656c5f-7f64-477d-91d2-9ac11a8c69eb', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b2181331-c9d0-437e-82f6-f4c23ebbfc6f', 'concept'::public.curated_course_node_type, 'Roughing, refining, and finishing', null, 1),
  ('99ac64ae-e9a7-42f3-a9c5-40fc880531d9', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b2181331-c9d0-437e-82f6-f4c23ebbfc6f', 'concept'::public.curated_course_node_type, 'Grain, direction, and fracture', null, 2),
  ('8015d103-e6f9-4705-a2d4-66a8de37f432', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b2181331-c9d0-437e-82f6-f4c23ebbfc6f', 'concept'::public.curated_course_node_type, 'Relief versus freestanding carving', null, 3),
  ('4971a7e1-c691-4c30-a934-03a9b007358e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '7584b66a-2a78-49d3-95dd-fe523edd9618', 'subtopic'::public.curated_course_node_type, 'Materials for Subtractive Work', 'The point is to match tool, material, and ambition so the process is feasible and expressive.', 1),
  ('a9e166dd-c16c-4059-9a40-a7ca5f747e59', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '4971a7e1-c691-4c30-a934-03a9b007358e', 'concept'::public.curated_course_node_type, 'Foam and plaster blocks', null, 0),
  ('bcb56d8e-6c5f-4cd2-b9d1-7aec536a58b1', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '4971a7e1-c691-4c30-a934-03a9b007358e', 'concept'::public.curated_course_node_type, 'Wood species and grain behavior', null, 1),
  ('931a67b2-f603-40d5-9385-4f4da6845c83', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '4971a7e1-c691-4c30-a934-03a9b007358e', 'concept'::public.curated_course_node_type, 'Stone overview and tool limits', null, 2),
  ('9da83b98-e931-44a7-aa7b-4b10acf31db3', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '4971a7e1-c691-4c30-a934-03a9b007358e', 'concept'::public.curated_course_node_type, 'Composite and reclaimed materials', null, 3),
  ('24e55257-9857-423c-85b5-1f295f978772', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '7584b66a-2a78-49d3-95dd-fe523edd9618', 'subtopic'::public.curated_course_node_type, 'Surface and Edge Control', 'Students learn that carving is not finished when the shape appears; surface is part of the idea.', 2),
  ('330d32ee-21c5-4e8a-aad8-00aa6959203d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '24e55257-9857-423c-85b5-1f295f978772', 'concept'::public.curated_course_node_type, 'Rasps, files, chisels, knives, and sandpaper', null, 0),
  ('bb80d6d6-e7d0-4c1c-b936-2d6c6588d3b9', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '24e55257-9857-423c-85b5-1f295f978772', 'concept'::public.curated_course_node_type, 'Edge sharpness and softness', null, 1),
  ('604a8bd2-e923-4ee1-b1ef-f53672e9160b', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '24e55257-9857-423c-85b5-1f295f978772', 'concept'::public.curated_course_node_type, 'Texture as evidence of process', null, 2),
  ('332bc089-b60d-4335-8e92-eaca3e1ba938', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '24e55257-9857-423c-85b5-1f295f978772', 'concept'::public.curated_course_node_type, 'Sealing, polishing, painting, and repair', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('ae6cff81-77ce-4dd4-85ce-6b0ee38199ca', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Construction: Wood, Metal, Fasteners, Welding, Joinery, and Structural Logic', 'Construction joins separate parts into a sculptural whole. Students learn structural thinking, fabrication sequencing, material compatibility, and the difference between a joint that merely holds and one that contributes meaning.', 5),
  ('5cfd8224-f777-4ce3-9f64-13d6c25ac8ae', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'ae6cff81-77ce-4dd4-85ce-6b0ee38199ca', 'subtopic'::public.curated_course_node_type, 'Wood and Joinery', 'Students learn basic woodworking as a foundation for frames, supports, pedestals, and finished sculptural forms.', 0),
  ('63f97fcc-c83c-4ceb-91ee-42f38c913614', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '5cfd8224-f777-4ce3-9f64-13d6c25ac8ae', 'concept'::public.curated_course_node_type, 'Measuring, cutting, drilling, and sanding', null, 0),
  ('8fbf6975-52ce-4d9f-9faf-d40134911adc', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '5cfd8224-f777-4ce3-9f64-13d6c25ac8ae', 'concept'::public.curated_course_node_type, 'Butt, lap, miter, and dowel joints', null, 1),
  ('9b7da7a2-8fbc-4f45-bcee-2ec1bd1a947a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '5cfd8224-f777-4ce3-9f64-13d6c25ac8ae', 'concept'::public.curated_course_node_type, 'Screws, bolts, glue, and clamps', null, 2),
  ('fefd2402-1aef-4afd-875a-3233ebf12664', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '5cfd8224-f777-4ce3-9f64-13d6c25ac8ae', 'concept'::public.curated_course_node_type, 'Frames, boxes, bases, and armatures', null, 3),
  ('e1141d64-ef73-4b69-9a2b-528e41d78e7f', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'ae6cff81-77ce-4dd4-85ce-6b0ee38199ca', 'subtopic'::public.curated_course_node_type, 'Metal and Welding Overview', 'The gist is to understand metal as line, mass, structure, and surface, with strong attention to supervised safety.', 1),
  ('a9590fe3-88fb-4572-988c-01732a75a71b', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'e1141d64-ef73-4b69-9a2b-528e41d78e7f', 'concept'::public.curated_course_node_type, 'Cutting, grinding, drilling, and bending', null, 0),
  ('f34a2d16-893a-4e92-9485-14b52417d58e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'e1141d64-ef73-4b69-9a2b-528e41d78e7f', 'concept'::public.curated_course_node_type, 'Welding concepts and shop protocols', null, 1),
  ('4a0d3990-f799-4b12-842d-08dd748b7e20', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'e1141d64-ef73-4b69-9a2b-528e41d78e7f', 'concept'::public.curated_course_node_type, 'Fasteners and mechanical connections', null, 2),
  ('a5b3797c-daba-4364-a0ff-db9e160389be', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'e1141d64-ef73-4b69-9a2b-528e41d78e7f', 'concept'::public.curated_course_node_type, 'Rust, patina, paint, and finish', null, 3),
  ('853d1868-1d0c-4a3c-89b2-4306a057ae5f', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'ae6cff81-77ce-4dd4-85ce-6b0ee38199ca', 'subtopic'::public.curated_course_node_type, 'Structural Logic and Fabrication Plans', 'Students learn to design the making process before the final object fails or becomes impossible to transport.', 2),
  ('25b56cb7-3c45-4829-9c6b-1b1aa70e8c93', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '853d1868-1d0c-4a3c-89b2-4306a057ae5f', 'concept'::public.curated_course_node_type, 'Load paths and stress points', null, 0),
  ('ca89c8af-4e79-4d2b-8ac2-8ae642427886', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '853d1868-1d0c-4a3c-89b2-4306a057ae5f', 'concept'::public.curated_course_node_type, 'Modular construction and disassembly', null, 1),
  ('fdd0adcf-9005-4b2d-b2c1-d6dd6df2f90c', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '853d1868-1d0c-4a3c-89b2-4306a057ae5f', 'concept'::public.curated_course_node_type, 'Templates, jigs, and mockups', null, 2),
  ('8dfdf7a5-1061-42f0-a818-2bd3d8ec9aad', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '853d1868-1d0c-4a3c-89b2-4306a057ae5f', 'concept'::public.curated_course_node_type, 'Transport, storage, and installation constraints', null, 3),
  ('b51c5ebb-0327-4af3-ba2d-3887ec834b9b', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Casting and Moldmaking: Plaster, Resin, Rubber, Bronze Overview, and Multiples', 'Casting and moldmaking introduce replication, translation, and transformation. Students learn how a form can move across materials, scales, editions, and levels of finish.', 6),
  ('deda63f9-e31e-4f43-bbec-583ed0b216b3', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b51c5ebb-0327-4af3-ba2d-3887ec834b9b', 'subtopic'::public.curated_course_node_type, 'Mold Types and Planning', 'Students learn that mold design is sculptural problem-solving: every undercut, seam, key, and pour path matters.', 0),
  ('27df011f-cdc1-4a89-bba6-6ff78df1ca40', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'deda63f9-e31e-4f43-bbec-583ed0b216b3', 'concept'::public.curated_course_node_type, 'One-part and two-part molds', null, 0),
  ('8f89713d-3e9d-4fa0-bdb3-cf91e59193e3', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'deda63f9-e31e-4f43-bbec-583ed0b216b3', 'concept'::public.curated_course_node_type, 'Flexible rubber molds', null, 1),
  ('41797108-3073-441c-8642-9688e491eb2a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'deda63f9-e31e-4f43-bbec-583ed0b216b3', 'concept'::public.curated_course_node_type, 'Keys, registration, and release agents', null, 2),
  ('43d1047e-3386-4dc6-bce4-63d170bc0bd1', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'deda63f9-e31e-4f43-bbec-583ed0b216b3', 'concept'::public.curated_course_node_type, 'Undercuts, vents, and pour gates', null, 3),
  ('a003b408-da4a-40f7-8866-d861ead4a85e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b51c5ebb-0327-4af3-ba2d-3887ec834b9b', 'subtopic'::public.curated_course_node_type, 'Casting Materials and Processes', 'The point is to understand how different casting materials behave and what each adds to meaning.', 1),
  ('11da7daa-aa4b-41ca-9d29-45f547a55c81', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'a003b408-da4a-40f7-8866-d861ead4a85e', 'concept'::public.curated_course_node_type, 'Plaster, cement, wax, resin, and slip overview', null, 0),
  ('824f8c33-81cc-49bf-893b-38e5a23b796b', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'a003b408-da4a-40f7-8866-d861ead4a85e', 'concept'::public.curated_course_node_type, 'Mixing ratios and cure times', null, 1),
  ('5af3c223-080a-48fd-8f69-fa5e45a6fea3', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'a003b408-da4a-40f7-8866-d861ead4a85e', 'concept'::public.curated_course_node_type, 'Colorants, fillers, and inclusions', null, 2),
  ('78ada06a-3625-4ec8-af34-cf2eede4761b', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'a003b408-da4a-40f7-8866-d861ead4a85e', 'concept'::public.curated_course_node_type, 'Defects, bubbles, repairs, and cleanup', null, 3),
  ('b76809d7-aa60-4169-b671-0e4e196b0fe3', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b51c5ebb-0327-4af3-ba2d-3887ec834b9b', 'subtopic'::public.curated_course_node_type, 'Editions, Multiples, and Bronze Overview', 'Students learn casting as a way to think about repetition, variation, value, and professional production.', 2),
  ('1cdda518-d77e-4883-89a9-3f3b19e1442d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b76809d7-aa60-4169-b671-0e4e196b0fe3', 'concept'::public.curated_course_node_type, 'Editioning and record keeping', null, 0),
  ('7ee0f313-0796-466b-9780-0d4637c0780e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b76809d7-aa60-4169-b671-0e4e196b0fe3', 'concept'::public.curated_course_node_type, 'Lost-wax bronze concepts', null, 1),
  ('3bde1525-ed2c-4ab3-9c62-a1ab387f407a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b76809d7-aa60-4169-b671-0e4e196b0fe3', 'concept'::public.curated_course_node_type, 'Foundry collaboration and safety', null, 2),
  ('fcf6f890-d1a4-4ce6-acd2-67b046e4283a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b76809d7-aa60-4169-b671-0e4e196b0fe3', 'concept'::public.curated_course_node_type, 'Multiples, series, and installation strategies', null, 3),
  ('c1707b26-f30e-43fc-bb0e-307354939c46', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Assemblage, Found Objects, Mixed Media, and Readymade Strategies', 'Assemblage and found-object work sharpen selection, context, and juxtaposition. Students learn how existing materials carry histories and how composition can redirect those histories.', 7),
  ('03a46747-9636-4c26-b19a-d58bb7ca3829', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'c1707b26-f30e-43fc-bb0e-307354939c46', 'subtopic'::public.curated_course_node_type, 'Readymade and Object Selection', 'Students learn to see ordinary objects as carriers of use, class, labor, memory, design, and cultural meaning.', 0),
  ('4de8f4b5-ff37-4564-94c7-1de20433c8df', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '03a46747-9636-4c26-b19a-d58bb7ca3829', 'concept'::public.curated_course_node_type, 'Duchamp and readymade traditions', null, 0),
  ('2fa6664f-125a-44ca-8c67-162959752171', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '03a46747-9636-4c26-b19a-d58bb7ca3829', 'concept'::public.curated_course_node_type, 'Commodity, tool, archive, and relic', null, 1),
  ('467a1b0c-3955-44ab-b7df-f6809767687c', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '03a46747-9636-4c26-b19a-d58bb7ca3829', 'concept'::public.curated_course_node_type, 'Humor, irony, and displacement', null, 2),
  ('91d401da-78a7-4312-b44a-8a5639270bfa', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '03a46747-9636-4c26-b19a-d58bb7ca3829', 'concept'::public.curated_course_node_type, 'Ethics of source, ownership, and representation', null, 3),
  ('c9083c94-44f1-4844-a074-1aa957e5f0a5', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'c1707b26-f30e-43fc-bb0e-307354939c46', 'subtopic'::public.curated_course_node_type, 'Assemblage and Mixed Media', 'The gist is learning how unlike materials can hold together formally, structurally, and conceptually.', 1),
  ('ee2a8f23-4b6f-4b3b-92b5-e089cd9cbc46', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'c9083c94-44f1-4844-a074-1aa957e5f0a5', 'concept'::public.curated_course_node_type, 'Accumulation and collage in space', null, 0);
