  ('0e873718-0836-475c-8c09-9ecdbc03c7af', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '5fcc304d-a98c-4f9a-8c8d-deaf50cd18ab', 'concept'::public.curated_course_node_type, 'Waste, reuse, and environmental critique', null, 2),
  ('3aaea0e0-295e-4767-950d-242389d4c2d8', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '5fcc304d-a98c-4f9a-8c8d-deaf50cd18ab', 'concept'::public.curated_course_node_type, 'Display as argument', null, 3),
  ('1899a9ec-e1e5-4084-b3c9-049848771d7e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Installation, Site-Specific, Public, and Socially Engaged Sculpture', 'This unit moves sculpture beyond the isolated studio object. Students learn to design for rooms, sites, institutions, publics, landscapes, communities, and viewer participation.', 8),
  ('4733812f-f458-4ec9-b169-c3441cf5a0fd', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '1899a9ec-e1e5-4084-b3c9-049848771d7e', 'subtopic'::public.curated_course_node_type, 'Installation and Spatial Sequence', 'Students learn to orchestrate how viewers enter, move, pause, look, listen, and exit.', 0),
  ('8c2b320d-266f-4772-b2d0-7b7aa9333f4b', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '4733812f-f458-4ec9-b169-c3441cf5a0fd', 'concept'::public.curated_course_node_type, 'Floor plans and circulation', null, 0),
  ('72b5bf94-c78f-4fe5-9873-f0005255e72a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '4733812f-f458-4ec9-b169-c3441cf5a0fd', 'concept'::public.curated_course_node_type, 'Sight lines, thresholds, and pacing', null, 1),
  ('b4e4bc36-234d-467b-bd29-77f7a6a77663', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '4733812f-f458-4ec9-b169-c3441cf5a0fd', 'concept'::public.curated_course_node_type, 'Light, sound, projection, and atmosphere', null, 2),
  ('62988441-8b71-48ed-b2cb-0b3df8d719b4', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '4733812f-f458-4ec9-b169-c3441cf5a0fd', 'concept'::public.curated_course_node_type, 'Multi-part works and spatial rhythm', null, 3),
  ('0261f0b3-76dc-41f3-985d-ad172226e94a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '1899a9ec-e1e5-4084-b3c9-049848771d7e', 'subtopic'::public.curated_course_node_type, 'Site-Specific and Public Work', 'The point is to understand that place is not a backdrop; it is part of the sculpture.', 1),
  ('0bebf6b0-cf17-43e5-a911-68ed522679ec', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0261f0b3-76dc-41f3-985d-ad172226e94a', 'concept'::public.curated_course_node_type, 'Site research and mapping', null, 0),
  ('002bd011-c49a-4916-a620-be6f64e869f8', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0261f0b3-76dc-41f3-985d-ad172226e94a', 'concept'::public.curated_course_node_type, 'Architecture, landscape, and history', null, 1),
  ('0d85dbf5-519b-4d82-82a2-562b984f4c9e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0261f0b3-76dc-41f3-985d-ad172226e94a', 'concept'::public.curated_course_node_type, 'Public permissions and stakeholders', null, 2),
  ('7d8bdc63-d6d4-4124-850a-d0348a0fde6a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0261f0b3-76dc-41f3-985d-ad172226e94a', 'concept'::public.curated_course_node_type, 'Weather, durability, maintenance, and safety', null, 3),
  ('20f10863-e671-48f7-afe8-19a9f5672072', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '1899a9ec-e1e5-4084-b3c9-049848771d7e', 'subtopic'::public.curated_course_node_type, 'Social and Participatory Practice', 'Students learn how sculpture can operate as event, collaboration, service, protest, or community encounter.', 2),
  ('aded5d42-67ab-4204-9b2c-3d26a49eb654', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '20f10863-e671-48f7-afe8-19a9f5672072', 'concept'::public.curated_course_node_type, 'Audience participation and consent', null, 0),
  ('acde9b42-a5d9-4129-a166-0fa1369e5d24', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '20f10863-e671-48f7-afe8-19a9f5672072', 'concept'::public.curated_course_node_type, 'Community research and accountability', null, 1),
  ('2cf3a6bb-f560-4c15-aa01-69ead91bd347', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '20f10863-e671-48f7-afe8-19a9f5672072', 'concept'::public.curated_course_node_type, 'Documentation of ephemeral work', null, 2),
  ('f6ebf10e-ad14-49c0-8706-ef697c44d345', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '20f10863-e671-48f7-afe8-19a9f5672072', 'concept'::public.curated_course_node_type, 'Ethics of collaboration and representation', null, 3),
  ('aa253d74-68d7-4e90-8b1e-a184eedf3382', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Digital Modeling, 3D Scanning, CNC/Laser/3D Printing, and Hybrid Fabrication', 'Digital tools expand what sculptors can model, test, fabricate, and document. Students learn to combine hand processes with precise digital workflows without letting software flatten artistic judgment.', 9),
  ('ce808bfa-cc38-4358-b800-3a0d264d0888', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'aa253d74-68d7-4e90-8b1e-a184eedf3382', 'subtopic'::public.curated_course_node_type, '3D Modeling and Visualization', 'Students use digital modeling to test scale, form, installation, and fabrication before committing material resources.', 0),
  ('3530c56d-94e5-4edd-82d8-780820e53a17', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'ce808bfa-cc38-4358-b800-3a0d264d0888', 'concept'::public.curated_course_node_type, 'Rhino, SketchUp, and mesh/NURBS concepts', null, 0),
  ('f3cbe058-2db1-42c3-b2b2-3b2da87305a2', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'ce808bfa-cc38-4358-b800-3a0d264d0888', 'concept'::public.curated_course_node_type, 'Orthographic views and measurements', null, 1),
  ('91dae90e-123c-4b83-bb66-d3751af81e31', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'ce808bfa-cc38-4358-b800-3a0d264d0888', 'concept'::public.curated_course_node_type, 'Rendering and material previews', null, 2),
  ('8e02351b-c122-411f-8e6f-031389455c7a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'ce808bfa-cc38-4358-b800-3a0d264d0888', 'concept'::public.curated_course_node_type, 'Exporting files for fabrication', null, 3),
  ('46e4082b-b51b-46cd-a75a-3af3663a6789', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'aa253d74-68d7-4e90-8b1e-a184eedf3382', 'subtopic'::public.curated_course_node_type, 'Scanning, CNC, Laser, and 3D Printing', 'The gist is learning where digital fabrication is powerful and where it needs hand finishing or structural correction.', 1),
  ('6818602a-fbbc-4f15-ba65-e7e18e410cfc', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '46e4082b-b51b-46cd-a75a-3af3663a6789', 'concept'::public.curated_course_node_type, '3D scanning and mesh cleanup', null, 0),
  ('163433e5-63f0-47d9-a61c-46803b56c76e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '46e4082b-b51b-46cd-a75a-3af3663a6789', 'concept'::public.curated_course_node_type, 'CNC routing and tool paths overview', null, 1),
  ('3e64822d-d701-4209-9125-5d571673a411', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '46e4082b-b51b-46cd-a75a-3af3663a6789', 'concept'::public.curated_course_node_type, 'Laser cutting and kerf planning', null, 2),
  ('242eb22f-8113-4ee8-91ab-c9fddb5d0a0d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '46e4082b-b51b-46cd-a75a-3af3663a6789', 'concept'::public.curated_course_node_type, '3D printing supports, tolerances, and post-processing', null, 3),
  ('ef1a9551-8252-47f7-90e8-a0268f5c0ab9', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'aa253d74-68d7-4e90-8b1e-a184eedf3382', 'subtopic'::public.curated_course_node_type, 'Hybrid Fabrication', 'Students learn to move between screen, shop, and gallery through iterative prototypes.', 2),
  ('0293f15c-59f4-4618-a554-388e5f9cbbd7', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'ef1a9551-8252-47f7-90e8-a0268f5c0ab9', 'concept'::public.curated_course_node_type, 'Digital maquettes and physical mockups', null, 0),
  ('956189bc-aa4d-4881-abe9-41fcbc1e5acd', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'ef1a9551-8252-47f7-90e8-a0268f5c0ab9', 'concept'::public.curated_course_node_type, 'File naming and version control', null, 1),
  ('93442441-0b3c-4cca-b8a1-874a654a068c', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'ef1a9551-8252-47f7-90e8-a0268f5c0ab9', 'concept'::public.curated_course_node_type, 'Combining printed, cast, carved, and found parts', null, 2),
  ('eef2788f-0810-4ee8-b22c-5e56129ec4fc', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'ef1a9551-8252-47f7-90e8-a0268f5c0ab9', 'concept'::public.curated_course_node_type, 'Failure testing and tolerance adjustment', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('1508468a-c452-4f12-8cc3-ac4db5585162', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Surface, Finish, Color, Patina, Texture, and Conservation Awareness', 'Surface is not decoration after the fact; it affects touch, time, durability, light, and interpretation. Students learn to finish work intentionally and understand basic conservation consequences.', 10),
  ('52abe57e-493b-435a-a3f0-840f255d19fd', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '1508468a-c452-4f12-8cc3-ac4db5585162', 'subtopic'::public.curated_course_node_type, 'Color, Paint, and Patina', 'Students learn how color and patina can unify parts, disguise construction, reveal process, or change historical associations.', 0),
  ('fb4a0ce0-ce7f-4f96-bb29-dea484a55619', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '52abe57e-493b-435a-a3f0-840f255d19fd', 'concept'::public.curated_course_node_type, 'Primers, paints, stains, dyes, and pigments', null, 0),
  ('c9758d34-6150-46c8-b391-1f541bf564c2', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '52abe57e-493b-435a-a3f0-840f255d19fd', 'concept'::public.curated_course_node_type, 'Metal oxidation and patina basics', null, 1),
  ('7b70e6bb-8618-46ed-9534-2dd46ae461e6', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '52abe57e-493b-435a-a3f0-840f255d19fd', 'concept'::public.curated_course_node_type, 'Color systems and spatial effects', null, 2),
  ('e65d667d-2f88-4f56-8571-ed0bff3d0396', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '52abe57e-493b-435a-a3f0-840f255d19fd', 'concept'::public.curated_course_node_type, 'Testing finish samples', null, 3),
  ('819bb141-8dee-4b63-9811-6d27d13df753', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '1508468a-c452-4f12-8cc3-ac4db5585162', 'subtopic'::public.curated_course_node_type, 'Texture and Tactility', 'The point is to understand how surface invites or refuses touch and how texture changes light.', 1),
  ('7d6185fa-de93-477d-8cba-1933a1b25818', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '819bb141-8dee-4b63-9811-6d27d13df753', 'concept'::public.curated_course_node_type, 'Polished, matte, rough, porous, and reflective surfaces', null, 0),
  ('3b31c2f9-c1b8-42d9-b2fa-c29bc6d4419f', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '819bb141-8dee-4b63-9811-6d27d13df753', 'concept'::public.curated_course_node_type, 'Tool marks and handmade evidence', null, 1),
  ('bacb9bd7-ffa1-49e1-bd29-72b6674ca83a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '819bb141-8dee-4b63-9811-6d27d13df753', 'concept'::public.curated_course_node_type, 'Applied skins, coatings, and veneers', null, 2),
  ('119e1847-4fc4-4bf1-9e14-5ede2cdaee1b', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '819bb141-8dee-4b63-9811-6d27d13df753', 'concept'::public.curated_course_node_type, 'Texture as metaphor and material fact', null, 3),
  ('90cad117-262e-4691-a700-028d2eeb1368', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '1508468a-c452-4f12-8cc3-ac4db5585162', 'subtopic'::public.curated_course_node_type, 'Durability and Conservation Awareness', 'Students learn to anticipate aging, cracking, fading, rust, pests, water, ultraviolet exposure, and handling damage.', 2),
  ('731aea91-2a57-4a34-b90a-cd5574f9a36b', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '90cad117-262e-4691-a700-028d2eeb1368', 'concept'::public.curated_course_node_type, 'Archival versus temporary choices', null, 0),
  ('138f8c97-43ae-4038-b78d-4615bf7a0146', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '90cad117-262e-4691-a700-028d2eeb1368', 'concept'::public.curated_course_node_type, 'Compatibility between materials', null, 1),
  ('02456d5a-458d-4446-8748-ffa76b84fb7a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '90cad117-262e-4691-a700-028d2eeb1368', 'concept'::public.curated_course_node_type, 'Cleaning and repair records', null, 2),
  ('4c347da7-c0ea-4707-a58f-8fc89cc56347', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '90cad117-262e-4691-a700-028d2eeb1368', 'concept'::public.curated_course_node_type, 'Storage, packing, and maintenance instructions', null, 3),
  ('fc379c50-a870-4fa1-a40b-22562c6c379b', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Sculptural Traditions, Contemporary Sculpture, and Critical Theory', 'This unit situates studio work within long, contested histories. Students study sculptural traditions and contemporary theory so their work can enter larger conversations with intelligence.', 11),
  ('b7c85872-40bf-49a4-9b1a-2db8bf9a58e9', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'fc379c50-a870-4fa1-a40b-22562c6c379b', 'subtopic'::public.curated_course_node_type, 'Historical Traditions', 'Students build a broad reference base across cultures, functions, materials, monuments, ritual objects, and museum histories.', 0),
  ('df82f216-bf4e-4ca5-a534-78fb167c5f2a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b7c85872-40bf-49a4-9b1a-2db8bf9a58e9', 'concept'::public.curated_course_node_type, 'Ancient, classical, indigenous, African, Asian, European, and American examples', null, 0),
  ('e8240c11-ac53-43f5-bb86-580e4fae5ed7', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b7c85872-40bf-49a4-9b1a-2db8bf9a58e9', 'concept'::public.curated_course_node_type, 'Ritual, memorial, religious, and civic functions', null, 1),
  ('56345f84-31ea-4c47-a98c-a3539eea6a73', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b7c85872-40bf-49a4-9b1a-2db8bf9a58e9', 'concept'::public.curated_course_node_type, 'Materials and patronage', null, 2),
  ('2df702fd-026f-4767-8ead-d9958d6e04a9', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b7c85872-40bf-49a4-9b1a-2db8bf9a58e9', 'concept'::public.curated_course_node_type, 'Museum display and colonial collecting histories', null, 3),
  ('fd6ac2ff-1dd6-499b-aebb-2ed73ffca635', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'fc379c50-a870-4fa1-a40b-22562c6c379b', 'subtopic'::public.curated_course_node_type, 'Modern and Contemporary Sculpture', 'The gist is understanding how sculpture changed through abstraction, industrial materials, minimalism, installation, performance, and new media.', 1),
  ('7d3f3a45-2dc2-457a-a7ce-995ab92c39e9', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'fd6ac2ff-1dd6-499b-aebb-2ed73ffca635', 'concept'::public.curated_course_node_type, 'Modernism and the expanded field', null, 0),
  ('bd54685a-b61e-4381-8128-ffa3bce42e9c', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'fd6ac2ff-1dd6-499b-aebb-2ed73ffca635', 'concept'::public.curated_course_node_type, 'Minimalism and postminimalism', null, 1),
  ('b6c58495-e87c-48f1-96d7-f645de0d8c45', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'fd6ac2ff-1dd6-499b-aebb-2ed73ffca635', 'concept'::public.curated_course_node_type, 'Feminist, queer, and decolonial sculpture', null, 2),
  ('cf92821f-d293-4eb1-9b0f-19fcba559084', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'fd6ac2ff-1dd6-499b-aebb-2ed73ffca635', 'concept'::public.curated_course_node_type, 'Ecology, technology, and global contemporary practice', null, 3),
  ('6678ce21-b481-40ef-a737-179c965099db', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'fc379c50-a870-4fa1-a40b-22562c6c379b', 'subtopic'::public.curated_course_node_type, 'Critical Theory for Makers', 'Students learn useful theory as studio equipment, not as decorative vocabulary.', 2),
  ('2c437bd7-0bf1-4045-8ddb-fabcc868f2b2', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '6678ce21-b481-40ef-a737-179c965099db', 'concept'::public.curated_course_node_type, 'Phenomenology and embodiment', null, 0),
  ('1406aec8-2c03-4549-a07b-9c64e396178b', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '6678ce21-b481-40ef-a737-179c965099db', 'concept'::public.curated_course_node_type, 'Semiotics and material culture', null, 1),
  ('40cd555d-e211-4a2f-af1b-94dd377f7fee', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '6678ce21-b481-40ef-a737-179c965099db', 'concept'::public.curated_course_node_type, 'Institutional critique', null, 2),
  ('5f3a5762-808a-4a1b-856a-583464a6e969', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '6678ce21-b481-40ef-a737-179c965099db', 'concept'::public.curated_course_node_type, 'More-than-human, ecological, and networked thinking', null, 3),
  ('162997a9-9ca6-416c-b188-3fa8643ed8f0', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Critique, Documentation, Artist Statements, and Portfolio Development', 'Sculpture must be made, discussed, photographed, written about, and remembered. This unit builds habits for critique, documentation, statements, and portfolio development.', 12),
  ('78c6d416-1563-4b7f-b4c2-bab14fa66a31', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '162997a9-9ca6-416c-b188-3fa8643ed8f0', 'subtopic'::public.curated_course_node_type, 'Critique Methods', 'Students learn to give and receive precise, generous, rigorous feedback that can change the work.', 0),
  ('cdac0e94-d2c1-49c3-8da2-3447c0a106f7', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '78c6d416-1563-4b7f-b4c2-bab14fa66a31', 'concept'::public.curated_course_node_type, 'Description before judgment', null, 0),
  ('6569082b-ea6c-4cf5-9a2b-6c24a54b16e7', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '78c6d416-1563-4b7f-b4c2-bab14fa66a31', 'concept'::public.curated_course_node_type, 'Formal, material, conceptual, and contextual critique', null, 1),
  ('ef81a686-1797-476f-872c-4b5b3a0f67ed', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '78c6d416-1563-4b7f-b4c2-bab14fa66a31', 'concept'::public.curated_course_node_type, 'Questions, evidence, and revision paths', null, 2),
  ('8d796f7a-1372-4e69-a9b8-87c7440c1913', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '78c6d416-1563-4b7f-b4c2-bab14fa66a31', 'concept'::public.curated_course_node_type, 'Peer review and self-assessment', null, 3),
  ('b41dab26-30ee-4c4e-af07-c963fd4ffb15', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '162997a9-9ca6-416c-b188-3fa8643ed8f0', 'subtopic'::public.curated_course_node_type, 'Documentation', 'The point is to preserve spatial work through photographs, video, diagrams, captions, and installation records.', 1),
  ('2e2efa01-1f5e-43e8-8f9c-a99235902090', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b41dab26-30ee-4c4e-af07-c963fd4ffb15', 'concept'::public.curated_course_node_type, 'Lighting and background choices', null, 0);
