  ('2cba22e1-d6d3-4745-9a9a-8902e8c2a512', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b41dab26-30ee-4c4e-af07-c963fd4ffb15', 'concept'::public.curated_course_node_type, 'Scale figures and detail shots', null, 1),
