  ('0fd0aabf-d8ef-4fff-a673-e98db6e6a08f', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'f29b3502-73cd-4b84-a7ed-12b17ca1a115', 'concept'::public.curated_course_node_type, 'Portfolio sequencing and captions', null, 2),
  ('4609973f-f045-4142-bec4-bf111819e621', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'f29b3502-73cd-4b84-a7ed-12b17ca1a115', 'concept'::public.curated_course_node_type, 'CV, website, and application readiness', null, 3),
  ('aefd2d20-ba05-40a5-b41d-5d35d28fa200', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Exhibition Design, Accessibility, Installation Safety, Rights, and Deinstallation', 'Exhibition planning turns finished work into a responsible public encounter. Students learn to install with attention to accessibility, hardware, labels, rights, audience safety, and deinstallation.', 13),
  ('9172cc3c-2193-4d3f-97ac-e8b7615e77fc', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'aefd2d20-ba05-40a5-b41d-5d35d28fa200', 'subtopic'::public.curated_course_node_type, 'Exhibition Layout and Accessibility', 'Students learn to design displays that respect bodies, movement, visibility, sensory access, and interpretive clarity.', 0),
  ('373d214e-9a96-4649-bf7a-98904f3c1a86', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '9172cc3c-2193-4d3f-97ac-e8b7615e77fc', 'concept'::public.curated_course_node_type, 'Floor plans and object spacing', null, 0),
  ('7816bdc4-5137-47df-ba81-502332f1c6ea', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '9172cc3c-2193-4d3f-97ac-e8b7615e77fc', 'concept'::public.curated_course_node_type, 'Accessible routes and viewing heights', null, 1),
  ('4e7ea90d-7152-4e93-ac2d-5c087d79967d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '9172cc3c-2193-4d3f-97ac-e8b7615e77fc', 'concept'::public.curated_course_node_type, 'Lighting, sound, projection, and sensory load', null, 2),
  ('d2fb02de-31eb-4863-849c-2768162f4f12', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '9172cc3c-2193-4d3f-97ac-e8b7615e77fc', 'concept'::public.curated_course_node_type, 'Labels, wall text, and plain-language access', null, 3),
  ('24713b7f-8c3f-4518-b230-3f9111b46043', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'aefd2d20-ba05-40a5-b41d-5d35d28fa200', 'subtopic'::public.curated_course_node_type, 'Installation Safety and Rights', 'The gist is to prevent harm and professionalize the practical details that make exhibitions possible.', 1),
  ('c5eb7604-3fc3-433a-87e2-680a617696a0', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '24713b7f-8c3f-4518-b230-3f9111b46043', 'concept'::public.curated_course_node_type, 'Anchoring, suspension, pedestals, barriers, and load limits', null, 0),
  ('d714a501-5ce7-4c9c-a1c8-cab9b953f99d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '24713b7f-8c3f-4518-b230-3f9111b46043', 'concept'::public.curated_course_node_type, 'Electrical, trip, sharp-edge, and fire concerns', null, 1),
  ('90826fb8-538a-4c51-bd80-2f73de4d6d98', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '24713b7f-8c3f-4518-b230-3f9111b46043', 'concept'::public.curated_course_node_type, 'Image, sound, object, and participant permissions', null, 2),
  ('1cd2dc89-c10b-4d32-b9c9-bbba56440854', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '24713b7f-8c3f-4518-b230-3f9111b46043', 'concept'::public.curated_course_node_type, 'Insurance, loan forms, and condition reports overview', null, 3),
  ('4c305beb-41b5-4d9c-927c-79b3922d4e94', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'aefd2d20-ba05-40a5-b41d-5d35d28fa200', 'subtopic'::public.curated_course_node_type, 'Maintenance and Deinstallation', 'Students learn that the life of the work includes upkeep, removal, storage, disposal, and archive.', 2),
  ('7dfbb2a3-dec6-47cc-8c92-a78a27b7f6c9', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '4c305beb-41b5-4d9c-927c-79b3922d4e94', 'concept'::public.curated_course_node_type, 'Checklists and installation manuals', null, 0),
