  ('25375fd4-863b-46ad-995b-48f029373411', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '4c305beb-41b5-4d9c-927c-79b3922d4e94', 'concept'::public.curated_course_node_type, 'Packing, labeling, and storage', null, 2),
  ('3a3cf95f-e102-4f3d-b1ec-fc013a82173d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '4c305beb-41b5-4d9c-927c-79b3922d4e94', 'concept'::public.curated_course_node_type, 'Deinstallation, recycling, and waste planning', null, 3),
  ('36d83f7a-50b7-4725-885c-58991a9fb127', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', null, 'topic'::public.curated_course_node_type, 'Capstone Sculpture Studio: Proposal, Prototype, Fabricate, Install, Reflect', 'The capstone asks students to synthesize research, design, fabrication, installation, critique, and reflection into a coherent sculptural project with professional documentation.', 14),
  ('0d8a6e03-d8a5-4d5a-8300-6d83990328d8', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '36d83f7a-50b7-4725-885c-58991a9fb127', 'subtopic'::public.curated_course_node_type, 'Proposal and Research', 'Students learn to turn ambition into a feasible plan with references, materials, budget, timeline, and risk assessment.', 0),
  ('215aa7b1-f6f9-4aea-8ba4-9fea3de0558e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0d8a6e03-d8a5-4d5a-8300-6d83990328d8', 'concept'::public.curated_course_node_type, 'Concept statement and research images', null, 0),
