  ('0bc49168-0659-49d0-94cb-2b86777d0786', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0d8a6e03-d8a5-4d5a-8300-6d83990328d8', 'concept'::public.curated_course_node_type, 'Timeline and fabrication sequence', null, 2),
  ('82d81de2-29fe-4d5a-a13b-9f9f84f6aa2a', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '0d8a6e03-d8a5-4d5a-8300-6d83990328d8', 'concept'::public.curated_course_node_type, 'Safety and installation plan', null, 3),
  ('b18918e8-7915-47db-90fb-83a0dbcc6f92', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', '36d83f7a-50b7-4725-885c-58991a9fb127', 'subtopic'::public.curated_course_node_type, 'Prototype, Fabricate, Revise', 'The point is to make strategically: test early, fail usefully, revise visibly, and solve problems before final installation.', 1),
  ('daa85391-7c05-4aad-a2a7-d2f50390bbb8', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b18918e8-7915-47db-90fb-83a0dbcc6f92', 'concept'::public.curated_course_node_type, 'Maquettes and mockups', null, 0),
  ('9b753747-a77a-42dd-bf07-e95a0f6e8c3e', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b18918e8-7915-47db-90fb-83a0dbcc6f92', 'concept'::public.curated_course_node_type, 'Material tests and structural tests', null, 1),
  ('43bd9e9f-af96-4314-8e78-3f3a092dcd1d', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b18918e8-7915-47db-90fb-83a0dbcc6f92', 'concept'::public.curated_course_node_type, 'Critique-based revisions', null, 2),
  ('5b22c8bd-ecdc-45af-8c37-b3ce9015e7f8', 'f2a3b4c5-6d7e-4f64-9c34-4d5e6f7a8b04', 'b18918e8-7915-47db-90fb-83a0dbcc6f92', 'concept'::public.curated_course_node_type, 'Finishing and quality control', null, 3),
